    func wait(_ i:Int) async {if pending[i]==nil {await withCheckedContinuation {waiters[i]=$0}}}
    func resolve(_ i:Int,_ value:SyntheticInboxSelfAssignmentOutcome) {pending.removeValue(forKey:i)!.resume(returning:value)}
