actor ControlledSelfAssignmentRepository:InboxSelfAssignmentRepository {
    private var pending:CheckedContinuation<InboxSelfAssignmentSource,Never>?,waiter:CheckedContinuation<Void,Never>?
    func source(_ c:InboxConversationFilesContext) async throws -> InboxSelfAssignmentSource {await withCheckedContinuation {pending=$0;waiter?.resume();waiter=nil}}
    func wait() async {if pending==nil {await withCheckedContinuation {waiter=$0}}}
    func resolve(_ source:InboxSelfAssignmentSource) {pending!.resume(returning:source);pending=nil}
}
